parameters.jsCode:
const triggerData = $('Execute Workflow Trigger').first().json;
const llmOutput = $input.first().json;

// Try to extract JSON from the LLM response
let rawText = llmOutput.text || llmOutput.response || llmOutput.output || '';

// Strip markdown code fences if present
rawText = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    identifyPain: '',
    metrics: '',
    decisionCriteria: '',
    decisionProcess: '',
    economicBuyer: '',
    champion: '',
    nextStep: '',
    confidenceFlags: ['Budget unconfirmed', 'Authority unconfirmed', 'Timeline vague', 'Champion weak', 'Competition unknown']
  };
}

return [{
  json: {
    identifyPain: parsed.identifyPain || '',
    metrics: parsed.metrics || '',
    decisionCriteria: parsed.decisionCriteria || '',
    decisionProcess: parsed.decisionProcess || '',
    economicBuyer: parsed.economicBuyer || '',
    champion: parsed.champion || '',
    nextStep: parsed.nextStep || '',
    confidenceFlags: Array.isArray(parsed.confidenceFlags) ? parsed.confidenceFlags : [],
    meetingDate: triggerData.meetingDate || '',
    transcriptUrl: triggerData.transcriptUrl || '',
    lastCallSummary: triggerData.lastCallSummary || '',
    dealId: triggerData.dealId || '',
    dealName: triggerData.dealName || '',
    contactName: triggerData.contactName || '',
    slackChannelId: triggerData.slackChannelId || ''
  }
}];

